from autore import Modulo,estratto
from tikz_base import scrivi,n,a,rect,linea
m=Modulo('M03','Descrivere e visualizzare i dati','Distribuzioni, confronti e relazioni nelle misure geologiche')
def p(t,s,**kw):m.pagina(t,s,**kw)
def d(i,b):return scrivi('M03',i,b)
m.sezione_nuova('Domanda, unità e rappresentazione')
p('La descrizione delimita il risultato',
'''L’esplorazione statistica ricostruisce la distribuzione delle osservazioni rispetto a una domanda definita. Nel caso guida, 160 fossili sintetici appartengono a due morfotipi di pari numerosità; il diametro totale, quello interno e il diaframma descrivono aspetti distinti della geometria. Una sintesi del diametro riguarda pertanto una misura per individuo, mentre una sintesi per morfotipo riguarda gruppi di individui. La distinzione consente di scegliere il denominatore, riconoscere la variabilità conservata dalla figura e delimitare l’insieme al quale si riferisce la descrizione.''',destra='I valori del caso guida sono simulati. Le differenze fra morfotipi illustrano procedure descrittive e dipendono dalle regole generatrici del dataset; non costituiscono evidenza paleontologica raccolta sul terreno.',richiamo='La domanda stabilisce quali osservazioni e quali proprietà debbano essere rappresentate.',origine='M03:1–8,13–15')
p('Ogni punto rappresenta un’unità',
'''Quando una figura riporta soltanto le medie dei gruppi, molte distribuzioni diverse possono produrre gli stessi punti. Affiancare osservazioni individuali e sintesi permette invece di distinguere posizione, dispersione e numerosità. Il diagramma mostra il passaggio dagli individui al gruppo: ciascuna media deriva da un insieme identificato, il cui dettaglio viene parzialmente eliminato dall’aggregazione. Questa perdita deve essere considerata quando si sceglie la rappresentazione destinata alla discussione scientifica.''',tikz=d('D01',n(1.7,.4,'Individui')+n(5.7,.4,'Gruppo')+''.join(n(1.7,1.3+j*.8,r'$x_{%d}$'%(j+1)) for j in range(4))+a(2.6,2.5,4.4,2.5)+rect(4.6,1.7,7,3.4)+n(5.8,2.55,r'$\bar x,\ s,\ n$')+n(3.7,5.4,'La sintesi conserva alcune proprietà della distribuzione.',w=6.8)),richiamo='Il significato del simbolo grafico deve corrispondere all’unità dichiarata.',origine='M03:8–12')
c=estratto('M03','controlli',"d <- read.csv('dati/fossili_simulati.csv')\nx <- d$diametro_tot_um\nstopifnot(nrow(d)==160L,all(x>0))\ntable(d$morfotipo)\nc(n=length(x),media=mean(x),sd=sd(x))\nquantile(x,c(0,.25,.5,.75,1),type=7)")
p('Le sintesi preliminari orientano la lettura',
'''Prima di disegnare il diametro, il controllo della numerosità, della positività e dei quantili consente di verificare il dominio delle misure. Il numero delle osservazioni disponibili deve accompagnare ogni tabella, soprattutto quando variabili diverse presentano coperture differenti. L’esame iniziale può suggerire ipotesi sulla distribuzione; qualora tali ipotesi vengano sottoposte a verifica usando gli stessi dati, il percorso esplorativo deve essere dichiarato, poiché la selezione delle domande influisce sull’interpretazione inferenziale successiva.''',codice=c,richiamo='La tabella di controllo precede la scelta delle scale e delle classi del grafico.',origine='M03:9–12,97–98')

m.sezione_nuova('Frequenze, denominatori e pesi')
p('Una proporzione richiede un insieme di riferimento',
'''La frequenza assoluta conta le osservazioni di una categoria, mentre quella relativa le rapporta alla numerosità dell’insieme considerato. In una tabella a doppia entrata, la proporzione per riga descrive la composizione all’interno della categoria di riga; quella per colonna risponde a una domanda diversa. Se alcuni valori sono mancanti, occorre specificare se il denominatore comprenda tutte le unità oppure soltanto quelle classificate. Il denominatore esplicita questa scelta.''',formula=r'n_{ab}=\sum_i\mathbf1(A_i=a,B_i=b)\\ p_{b\mid a}=\frac{n_{ab}}{\sum_b n_{ab}}',destra='Una proporzione è priva di unità e appartiene all’intervallo fra zero e uno. Un tasso può invece avere dimensioni, come eventi per anno o difetti per centimetro quadrato, poiché il denominatore misura un’esposizione.',richiamo='Il denominatore distingue la domanda statistica a cui risponde la frequenza.',origine='M03:16–23')
p('L’aggregazione utilizza le numerosità',
'''Due livelli contengono rispettivamente 8 fossili Spiky su 10 e 54 su 90. La proporzione complessiva deriva da 62 individui su 100, poiché ogni fossile contribuisce una volta al conteggio. La media semplice delle due percentuali attribuirebbe invece lo stesso peso a livelli di numerosità differente. La figura separa le proporzioni entro livello dalla quota aggregata, chiarendo quale popolazione di unità sia rappresentata da ciascun valore.''',formula=r'\hat p=\frac{8+54}{10+90}=0,62\\ \hat p=\frac{10}{100}\,0,80+\frac{90}{100}\,0,60',figura='M03/F01',didascalia='Esempio costruito: le percentuali per livello e quella complessiva usano denominatori differenti.',richiamo='L’aggregazione di percentuali richiede i conteggi o pesi coerenti con l’unità di interesse.',origine='M03:22,24–25')
p('Il denominatore si legge nella tabella',
'''Una tabella dei conteggi conserva le informazioni necessarie per calcolare percentuali condizionate secondo entrambe le direzioni. Nel diagramma, le celle di una riga condividono il medesimo denominatore, mentre la somma di colonna rappresenta un altro insieme. Scrivere prima il conteggio e poi il rapporto evita che una percentuale venga interpretata come una proprietà intrinseca della cella. Il margine scelto appartiene alla definizione della quantità descritta.''',tikz=d('D02',n(3,.4,'Spiky')+n(5.5,.4,'Altri')+n(.8,1.7,'L1')+n(.8,3.1,'L2')+rect(1.8,1,6.8,2.4)+n(3,1.7,'8')+n(5.5,1.7,'2')+rect(1.8,2.5,6.8,3.8,'Quantum')+n(3,3.1,'54')+n(5.5,3.1,'36')+n(3.7,4.7,r'$p(\mathrm{Spiky}\mid L1)=8/10$')+n(3.7,5.7,r'$p(L1\mid\mathrm{Spiky})=8/62$')),richiamo='La direzione del condizionamento determina quali celle compongano il denominatore.',origine='M03:19–20')

m.sezione_nuova('Misure di posizione')
p('Media e mediana rispondono a criteri distinti',
'''La media aritmetica redistribuisce il totale osservato fra tutte le unità e minimizza la somma degli scarti quadratici. La mediana individua invece una posizione centrale nell’ordinamento e minimizza la somma degli scarti assoluti; per una numerosità pari può esistere un intervallo di minimizzatori, del quale R restituisce il punto medio dei due valori centrali. La scelta della sintesi dipende dalla proprietà che si intende descrivere, dalla scala di misura e dalla sensibilità desiderata agli estremi.''',formula=r'\bar x=\frac1n\sum_i x_i=\arg\min_a\sum_i(x_i-a)^2\\ \widetilde x\in\arg\min_a\sum_i|x_i-a|',destra='La moda descrive la categoria o il valore più frequente. Per una misura continua, un massimo dell’istogramma dipende dalla suddivisione in classi e non identifica automaticamente una moda stabile della popolazione.',richiamo='Ogni misura di posizione privilegia una proprietà della distribuzione.',origine='M03:26–29,31–33')
p('La sensibilità a un estremo è quantificabile',
'''Nei valori 3, 4, 5 e 100, la media è 28 mentre la mediana è 4,5. Sostituendo l’ultima osservazione con un valore crescente, la media varia linearmente, mentre la mediana rimane invariata finché l’ordinamento centrale viene conservato. Questa diversa sensibilità riguarda il comportamento delle sintesi; per decidere se correggere o escludere l’osservazione occorrono invece informazioni sulla misura e sul processo che l’ha prodotta.''',formula=r'\bar x(M)=\frac{12+M}{4},\quad M\ge5\\ \widetilde x(M)=4,5',figura='M03/F02',didascalia='Esempio deterministico. L’ultima osservazione varia da 5 a 100, mentre le prime tre restano fissate.',richiamo='La sensibilità della sintesi e la validità dell’osservazione costituiscono valutazioni distinte.',origine='M03:30,34–35')
p('La media ponderata conserva il totale pertinente',
'''Quando ciascun valore rappresenta una quantità diversa di materiale, la media ponderata combina i contributi secondo pesi esplicitamente definiti. Per la densità di un insieme di provini, i volumi forniscono i pesi che permettono di ricostruire il rapporto fra massa totale e volume totale. Se l’obiettivo riguarda invece il provino medio, ciascun individuo riceve lo stesso peso. Le due sintesi possono differire perché descrivono quantità scientifiche differenti.''',formula=r'\bar x_w=\frac{\sum_i w_i x_i}{\sum_i w_i}\\ \rho_{\mathrm{tot}}=\frac{\sum_i V_i\rho_i}{\sum_i V_i}',tikz=d('D03',rect(.4,1.2,2.1,3.6)+rect(2.2,1.2,7,3.6,'Quantum')+n(1.25,2.4,r'$w_1$',w=1.4)+n(4.6,2.4,r'$w_2$',w=3)+n(3.7,.5,'Contributi al totale')+a(1.3,3.9,3.4,4.8)+a(4.7,3.9,4,4.8,'Quantum')+n(3.7,5.6,r'$\sum_i w_i x_i\,/\,\sum_i w_i$')),richiamo='I pesi devono derivare dalla quantità che la sintesi intende rappresentare.',origine='M03:31')

m.sezione_nuova('Dispersione e quantili')
p('La varianza misura scarti quadratici',
'''Gli scarti dalla media sommano a zero, poiché la media conserva il totale. La loro somma quadratica evita la compensazione fra segni e definisce una misura di dispersione. La divisione per n−1 rende la varianza campionaria uno stimatore non distorto della varianza di una popolazione con secondo momento finito, sotto campionamento indipendente e identicamente distribuito. La deviazione standard riporta la dispersione nelle unità originarie, mentre la varianza conserva unità elevate al quadrato.''',formula=r'\sum_i(x_i-\bar x)=0\\ s^2=\frac{\sum_i(x_i-\bar x)^2}{n-1},\qquad s=\sqrt{s^2}',destra='Per i valori 4, 5 e 6 si ottiene s=1; per 0, 5 e 10 si ottiene s=5. La media è 5 in entrambi i casi, mentre ampiezza e dispersione differiscono.',richiamo='La stessa media può accompagnare distribuzioni di ampiezza molto diversa.',origine='M03:36–40,44–45')
p('Gli scarti conservano una geometria',
'''Il diagramma dispone tre valori lungo una scala e rappresenta la loro distanza dalla media. La cancellazione degli scarti firmati deriva dalla posizione del centro aritmetico; l’elevamento al quadrato rende invece più influenti le distanze maggiori. Poiché la varianza dipende dalla scala, una conversione delle unità moltiplica la deviazione standard per il valore assoluto del fattore di conversione e la varianza per il suo quadrato.''',formula=r'Y=a+bX\quad\Rightarrow\quad s_Y=|b|s_X',tikz=d('D04',linea(.5,3.2,7,3.2)+''.join(linea(x,3, x,3.4)+n(x,3.9,t) for x,t in [(1,'4'),(3.75,'5'),(6.5,'6')])+n(3.75,1,r'$\bar x=5$')+a(3.75,2.1,1,2.1)+a(3.75,2.1,6.5,2.1,'Quantum')+n(2,1.6,'−1')+n(5.4,1.6,'+1')+n(3.75,5.3,r'$(-1)^2+0^2+1^2=2$')),richiamo='La trasformazione delle unità deve essere applicata anche alle misure di dispersione.',origine='M03:38–40')
p('Un quantile richiede una convenzione',
'''Il quantile empirico associa a una probabilità una soglia ricavata dai valori ordinati. Nei campioni finiti esistono diverse convenzioni di interpolazione, che possono produrre risultati differenti pur utilizzando gli stessi dati. R offre nove definizioni nella funzione quantile; il tipo 7, adottato in questo modulo, interpola linearmente fra posizioni adiacenti. L’intervallo interquartile misura la distanza fra i quantili 0,75 e 0,25 e mantiene una relazione diretta con la parte centrale della distribuzione.''',formula=r'h=1+(n-1)p,\quad j=\lfloor h\rfloor\\ Q_7(p)=(1-h+j)x_{(j)}+(h-j)x_{(j+1)}',destra='La formula di interpolazione vale quando j<n; agli estremi si restituiscono minimo e massimo. Il coefficiente di variazione s/media richiede una scala a rapporti con zero significativo e una media sufficientemente lontana da zero.',richiamo='La convenzione dei quantili va specificata quando la riproduzione numerica richiede uguaglianza esatta.',origine='M03:41–43')

m.sezione_nuova('Distribuzioni e scelte di smoothing')
p('L’istogramma approssima la distribuzione',
'''L’istogramma suddivide la scala in intervalli e assegna a ogni classe un conteggio. Quando le ampiezze sono uguali, le altezze permettono il confronto diretto delle frequenze; con ampiezze differenti, una rappresentazione in densità deve dividere la frequenza relativa per la larghezza della classe. In tal modo l’area, anziché la sola altezza, conserva la probabilità empirica. La scelta delle classi controlla il dettaglio visibile e deve essere valutata rispetto alla numerosità e alla precisione delle misure.''',formula=r'h_j=\frac{n_j}{n\,\Delta_j},\qquad \sum_j h_j\Delta_j=1',figura='M03/F03',didascalia='Gli stessi 160 diametri sintetici sono rappresentati con classi di ampiezza 0,5 e 1 µm, usando assi comuni.',richiamo='La forma apparente va verificata rispetto a più suddivisioni ragionevoli della scala.',origine='M03:46–49,54–55,99')
p('L’area conserva la frequenza relativa',
'''Il diagramma confronta due classi con uguale frequenza relativa e larghezze differenti. Affinché le aree coincidano, la classe più ampia deve avere un’altezza inferiore. La densità possiede quindi l’inverso dell’unità della variabile: moltiplicandola per una larghezza si ottiene una quantità priva di dimensioni. Questa relazione chiarisce perché una densità possa superare uno senza violare alcuna proprietà delle probabilità.''',tikz=d('D05',linea(.7,4.5,7,4.5)+linea(.7,4.5,.7,.6)+rect(1.2,1.1,2.7,4.5)+rect(3.2,2.8,6.2,4.5,'Quantum')+n(1.95,5,'Δ')+n(4.7,5,'2Δ')+n(1.95,.6,'h')+n(4.7,2.2,'h/2')+n(3.7,5.9,'Aree uguali: stessa frequenza relativa.',w=6.8,size=11)),richiamo='Nell’istogramma in densità la probabilità empirica è rappresentata dall’area.',origine='M03:49')
p('Una miscela può generare più picchi',
'''La distribuzione complessiva dei diametri combina due gruppi, le cui forme vengono rappresentate mediante curve di densità. Una separazione fra picchi può dipendere da gruppi con posizioni differenti, sebbene l’aspetto della curva risenta anche dell’ampiezza di smoothing. La stima kernel distribuisce il contributo di ogni osservazione in un intorno: una banda piccola conserva oscillazioni locali, mentre una banda ampia attenua il dettaglio. L’interpretazione richiede pertanto il confronto con i punti e con gruppi definiti da informazioni indipendenti.''',formula=r'\widehat f_h(x)=\frac1{nh}\sum_i K\!\left(\frac{x-x_i}{h}\right)',figura='M03/F04',didascalia='Densità dei diametri per morfotipo e distribuzione complessiva. La banda impiegata è dichiarata nello script R.',richiamo='La forma stimata dipende dalla composizione del campione e dalla scelta della banda.',origine='M03:50–52,59')
p('La cumulativa evita la scelta delle classi',
'''La funzione cumulativa empirica riporta, per ogni soglia, la proporzione delle osservazioni che assumono un valore inferiore o uguale. Ogni individuo contribuisce un salto di ampiezza 1/n, oppure parte di un salto più grande quando più valori coincidono. La figura consente di leggere direttamente percentili e quote sotto soglia, mantenendo l’ordinamento completo dei dati. Il confronto fra cumulative può rivelare differenze di posizione o di forma che una sola media lascerebbe indeterminate.''',formula=r'\widehat F_n(x)=\frac1n\sum_{i=1}^n\mathbf1(x_i\le x)',figura='M03/F05',didascalia='Cumulative empiriche dei diametri dei due morfotipi; ogni gruppo contiene 80 osservazioni.',richiamo='La cumulativa rappresenta una quota di osservazioni, con valori compresi fra zero e uno.',origine='M03:53')

m.sezione_nuova('Confronti fra gruppi')
p('Il boxplot sintetizza un insieme ordinato',
'''Il boxplot mostra la posizione della mediana e l’estensione della parte centrale della distribuzione. Nella convenzione impiegata da ggplot2, i baffi raggiungono le osservazioni più estreme comprese entro 1,5 volte l’intervallo interquartile dai bordi della scatola. I valori esterni vengono rappresentati separatamente e richiedono un esame della provenienza. L’aggiunta dei punti individuali rende leggibili numerosità, sovrapposizione e possibili strutture che la scatola, da sola, comprime.''',formula=r'L=Q_1-1,5\,IQR,\quad U=Q_3+1,5\,IQR',figura='M03/F06',didascalia='Boxplot e osservazioni individuali. Lo spostamento orizzontale serve a distinguere i punti e non modifica il diametro.',richiamo='La posizione oltre i baffi segnala un valore da esaminare, senza determinarne la validità.',origine='M03:56–58,61–65,100')
p('Le soglie dei baffi differiscono dai baffi',
'''Le soglie calcolate dai quartili definiscono un intervallo convenzionale, mentre i baffi terminano su valori effettivamente osservati entro tale intervallo. Confondere queste due quantità attribuirebbe al grafico osservazioni inesistenti. Nel diagramma, il valore esterno viene conservato e identificato; la sua eventuale esclusione richiederebbe una motivazione riferita alla misurazione o al disegno, documentata separatamente dalla convenzione grafica.''',tikz=d('D06',linea(.5,3,7,3)+rect(2.2,2.1,4.8,3.9)+linea(3.5,2.1,3.5,3.9,'Quantum')+linea(1.2,2.6,1.2,3.4)+linea(5.7,2.6,5.7,3.4)+n(6.7,3,r'$\circ$')+n(2.2,4.5,r'$Q_1$')+n(4.8,4.5,r'$Q_3$')+n(3.5,1.3,'Mediana')+n(3.7,5.7,'I baffi terminano su osservazioni.',w=6.7)),richiamo='La convenzione del boxplot deve essere letta insieme alla distribuzione dei singoli valori.',origine='M03:57–58')
p('Il confronto richiede scale comuni',
'''Pannelli con limiti differenti possono attribuire la stessa estensione visiva a distribuzioni di ampiezza diversa. Quando l’obiettivo riguarda differenze di posizione e dispersione, scale comuni rendono confrontabili le distanze. Anche la numerosità deve essere esplicitata, poiché gruppi piccoli offrono minori possibilità di osservare valori estremi. La descrizione grafica può documentare una separazione campionaria, mentre l’estensione della conclusione a una popolazione richiede ipotesi e procedure inferenziali.''',figura='M03/F07',didascalia='Distribuzioni dei due gruppi in pannelli con gli stessi limiti e la stessa ampiezza delle classi.',richiamo='La coerenza delle scale permette di confrontare distanze grafiche e differenze quantitative.',origine='M03:60–65')

m.sezione_nuova('Relazioni fra misure')
p('Lo scatterplot conserva le coppie osservate',
'''Ogni punto dello scatterplot abbina due misure dello stesso fossile. La relazione fra diametro totale e diaframma viene descritta considerando direzione, forma, dispersione e presenza di gruppi. Il colore identifica il morfotipo, consentendo di verificare se una tendenza complessiva coincida con le tendenze interne. L’associazione grafica resta compatibile con più processi generativi, inclusi effetti della dimensione complessiva, variabili condivise e regole di costruzione del dataset.''',figura='M03/F08',didascalia='Diametro totale e diaframma, espressi in µm, per i 160 fossili sintetici.',richiamo='Le coppie di valori devono riferirsi alle medesime unità osservate.',origine='M03:66–68,70,73,101')
p('Una relazione può essere non lineare',
'''Una nuvola disposta intorno a una curva a U può avere correlazione lineare prossima a zero, pur conservando una relazione marcata fra le variabili. La correlazione di Pearson misura infatti una componente specifica dell’associazione, legata alla covariazione lineare. Il confronto fra strutture costruite rende visibile questo limite e giustifica l’esame dello scatterplot prima della sintesi numerica. Valori lontani lungo l’asse del predittore richiedono inoltre attenzione, poiché possono influenzare fortemente una retta stimata.''',formula=r'r=\frac{\sum_i(x_i-\bar x)(y_i-\bar y)}{\sqrt{\sum_i(x_i-\bar x)^2\sum_i(y_i-\bar y)^2}}',figura='M03/F09',didascalia='Relazione simulata a U: la forma simmetrica produce covarianza teorica nulla quando x è simmetrico e il rumore è indipendente.',richiamo='Una sintesi lineare deve essere interpretata dopo avere esaminato la forma della relazione.',origine='M03:69,72,74–75')
p('Le sovrapposizioni richiedono trasparenza',
'''Misure arrotondate possono produrre molti punti nella stessa posizione, rendendo la numerosità locale poco riconoscibile. Trasparenza, conteggi per cella o piccoli spostamenti grafici permettono di mostrare la concentrazione delle osservazioni. Qualora si introduca jitter, la didascalia deve chiarire che lo spostamento riguarda soltanto la rappresentazione. L’ampiezza viene scelta rispetto alla risoluzione delle misure, affinché il grafico conservi la scala quantitativa dell’analisi.''',destra='Per confrontare dati arrotondati al decimo di micrometro, uno spostamento grafico inferiore a metà di tale intervallo evita di confondere eccessivamente le classi adiacenti. I calcoli statistici continuano a utilizzare i valori originali.',richiamo='Una trasformazione grafica deve rimanere distinguibile da una trasformazione dei dati.',origine='M03:71')

m.sezione_nuova('Posizione e rappresentazione spaziale')
p('La copertura spaziale precede l’interpolazione',
'''Le coordinate acquistano significato attraverso un sistema di riferimento, che definisce unità, orientamento e interpretazione delle distanze. Una carta dei punti campionati permette di valutare dove l’informazione sia disponibile e quali aree rimangano scarsamente rappresentate. Se la raccolta si concentra lungo una strada, l’assenza di punti altrove descrive il disegno di osservazione. Una superficie interpolata introduce ipotesi sulla continuità del fenomeno e deve essere distinta dalle misure localizzate che la sostengono.''',figura='M03/F10',didascalia='Disegno spaziale sintetico in coordinate metriche locali: i punti si concentrano presso una linea di accesso.',richiamo='La distribuzione dei punti delimita il supporto empirico della rappresentazione spaziale.',origine='M03:76–79,82–85')
p('Il simbolo proporzionale rappresenta un’area',
'''Quando la quantità viene codificata mediante l’area di un cerchio, il raggio deve crescere con la radice quadrata del valore. Un raggio direttamente proporzionale alla misura amplificherebbe invece le differenze quadraticamente. La legenda deve mostrare grandezze di riferimento e unità, mentre la scelta cromatica deve rispecchiare l’ordine della variabile: una scala sequenziale descrive intensità crescenti, una divergente evidenzia scarti rispetto a un riferimento significativo.''',formula=r'A_i=c\,x_i,\qquad r_i=\sqrt{c\,x_i/\pi}',tikz=d('D07',r'\draw[fill=Classical!15,draw=Classical] (1.6,2.8) ellipse (.6 and .689655);'+r'\draw[fill=Quantum!15,draw=Quantum] (5.2,2.8) ellipse (1.2 and 1.37931);'+n(1.6,4.5,'x')+n(5.2,4.5,'4x')+n(3.7,.5,'Area proporzionale al valore')+n(3.7,5.7,'Un’area quadrupla richiede un raggio doppio.',w=6.8,size=11)),richiamo='La relazione fra valore e dimensione del simbolo deve essere dichiarata nella legenda.',origine='M03:80–81')

m.sezione_nuova('Scale e trasformazioni')
p('La scala logaritmica rende confrontabili i rapporti',
'''Su una scala logaritmica, intervalli grafici uguali corrispondono a rapporti uguali fra valori positivi. La trasformazione dei dati modifica invece la variabile analizzata e può cambiare la forma della distribuzione, la relazione fra misure e il significato di una media. Zeri e valori negativi richiedono una valutazione del processo di misura e del dominio: aggiungere arbitrariamente una costante modifica i rapporti e rende il risultato dipendente dalla scelta introdotta.''',formula=r'\log x_2-\log x_1=\log(x_2/x_1)',figura='M03/F11',didascalia='Valori positivi su scala logaritmica: da 1 a 10 e da 10 a 100 µm le distanze grafiche sono uguali.',richiamo='La scelta della scala deve rendere leggibile una proprietà quantitativa pertinente.',origine='M03:86–89,93–95')
p('La standardizzazione conserva la forma relativa',
'''La standardizzazione sottrae una posizione di riferimento e divide per una scala positiva, producendo una variabile priva di unità. Essendo affine, conserva l’ordinamento, le asimmetrie e le proporzioni fra distanze; cambia invece origine e unità di misura. Nel confronto predittivo, media e deviazione standard vengono stimate sul campione di addestramento e applicate senza ricalcolo ai nuovi dati, affinché la trasformazione non utilizzi informazione proveniente dall’insieme di valutazione.''',formula=r'z_i=\frac{x_i-\bar x_{\mathrm{train}}}{s_{\mathrm{train}}}',tikz=d('D08',rect(.3,.8,3.1,2.5)+n(1.7,1.65,'Campione di addestramento',w=2.5,size=11)+a(3.3,1.65,4,1.65)+rect(4.2,.8,7.1,2.5,'Quantum')+n(5.65,1.65,r'$\bar x_{\rm train},s_{\rm train}$',w=2.5)+a(5.65,2.8,5.65,4)+rect(.3,4.2,3.1,5.6)+n(1.7,4.9,'Nuova misura',w=2.5)+a(3.3,4.9,4,4.9)+n(5.65,4.9,r'$z_{\rm nuovo}$')),richiamo='I parametri della trasformazione devono rispettare la separazione fra addestramento e valutazione.',origine='M03:90–95')
c=estratto('M03','trasformazioni',"d <- read.csv('dati/fossili_simulati.csv')\nx <- d$diametro_tot_um\nz <- as.numeric(scale(x))\nstopifnot(abs(mean(z))<1e-12,\n          abs(sd(z)-1)<1e-12)\nc(media=mean(x),geometrica=exp(mean(log(x))))\nrange(z)")
p('La trasformazione modifica la quantità sintetizzata',
'''La media aritmetica dei logaritmi, riportata alla scala originale mediante l’esponenziale, produce la media geometrica. Tale quantità sintetizza variazioni moltiplicative ed è definita per osservazioni positive. Il codice la confronta con la media aritmetica e verifica le proprietà dello z-score sul campione usato per la standardizzazione. Questi controlli permettono di associare ogni comando alla quantità matematica che viene effettivamente calcolata.''',formula=r'g=\exp\!\left(\frac1n\sum_i\log x_i\right)=\left(\prod_i x_i\right)^{1/n}',codice=c,richiamo='La sintesi riportata deve identificare sia la trasformazione sia la scala finale.',origine='M03:87–95')

m.sezione_nuova('Laboratorio e verifica')
c=estratto('M03','grafico',"source('R/stile.R')\nd <- leggi('fossili_simulati.csv')\np <- ggplot(d,aes(diametro_tot_um,\n diaframma_um,colour=morfotipo))+\n geom_point(size=2,alpha=.75)+\n scale_colour_manual(values=geo[1:2])+\n labs(x='Diametro totale (µm)',\n      y='Diaframma (µm)')\nprint(p)")
p('Il codice esplicita le corrispondenze grafiche',
'''La chiamata aes associa variabili alle coordinate e al colore, mentre geom_point definisce il simbolo usato per ciascuna coppia. Le etichette dichiarano le unità e la scala cromatica conserva la stessa corrispondenza fra morfotipi utilizzata nelle altre figure. Questa separazione permette di modificare l’aspetto senza alterare il dataset, mantenendo riconoscibile quali scelte riguardino la rappresentazione e quali derivino dalle osservazioni.''',codice=c,richiamo='Le corrispondenze fra dati e proprietà grafiche devono essere leggibili nel codice.',origine='M03:96–102')
p('La didascalia delimita l’interpretazione',
'''Una didascalia scientifica identifica variabili, unità, numerosità, provenienza e trasformazioni necessarie alla lettura. Nel caso dei fossili, deve dichiarare la natura sintetica dei dati e il significato dei colori, precisando l’eventuale uso di jitter o smoothing. Il testo che accompagna la figura descrive poi una proprietà osservabile, come la differenza di posizione o la sovrapposizione, mantenendo distinta l’evidenza campionaria dalle spiegazioni del processo generativo.''',destra='Consegna: una tabella con numerosità e sintesi, un istogramma motivato dal confronto di due ampiezze, un grafico dei gruppi con osservazioni individuali e uno scatterplot. Per ciascun prodotto, specificare la domanda, il denominatore o l’unità e una limitazione interpretativa.',richiamo='La figura deve poter essere interpretata attraverso dati, legenda e didascalia.',origine='M03:98–107,110')
p('Verificare le scelte mediante controesempi',
'''Si considerino due livelli con proporzioni 8/10 e 54/90, due campioni con media 5 e dispersioni differenti, e una relazione simmetrica a U. La proporzione aggregata è 0,62; la media comune lascia indeterminata la dispersione; una correlazione lineare nulla può accompagnare una relazione non lineare. Questi controesempi permettono di verificare se una sintesi venga interpretata entro il proprio significato matematico. La consegna deve includere i calcoli, le figure e una spiegazione del passaggio logico che ciascun esempio mette alla prova.''',destra='Valutazione: coerenza delle unità e dei denominatori; corrispondenza fra domanda e rappresentazione; leggibilità delle scale; riproducibilità del codice; precisione delle conclusioni rispetto al campione descritto.',richiamo='Un controesempio rende riconoscibile il limite di una sintesi statistica.',origine='M03:24–25,34–35,44–45,74–75,104–107')
p('Riferimenti per definizioni e convenzioni',
'''La documentazione delle funzioni quantile, sd e ecdf precisa le convenzioni numeriche impiegate nelle sintesi. I riferimenti di ggplot2 descrivono il calcolo degli istogrammi, dei boxplot e delle densità, mentre il manuale introduttivo di R collega vettori, indicizzazione e rappresentazioni. I sorgenti distribuiti con il modulo conservano scelte di scala, ampiezze delle classi e semi casuali, consentendo di ricostruire le figure senza ricorrere a impostazioni implicite.''',destra='R Core Team: An Introduction to R; documentazione stats::quantile, stats::sd, stats::ecdf.\n\nggplot2: riferimenti geom_histogram, geom_boxplot e geom_density.\n\nURL e versioni dell’ambiente sono riportati nella bibliografia e nel registro di esecuzione del corso.',richiamo='Le convenzioni del software fanno parte della definizione operativa delle sintesi.',origine='M03:108–109',fonti='R Core Team · ggplot2')
m.salva()
